    module2.exports = "/**\r\n * Track do Oodeus \u2014 [R3-port] cadastro_edital.html \u2014 Script 2 (original 2508\u20132635)\r\n * Fluxo de edi\xE7\xE3o via URL, p\xF3s data.js no original; no plugin roda dentro do\r\n * MESMO wrapper `new Function` do Script1 (env l\xE9xico compartilhado \u2014 l\xEA\r\n * escolherTipo/logoRealizadoBase64 etc. direto) e DEPOIS do nav boot (desvio\r\n * documentado \u2014 ver shell.js/script1). \xC9 100% DOMContentLoaded-wrapped: o\r\n * shell dispara o DOMContentLoaded sint\xE9tico por render (no plugin o real j\xE1\r\n * disparou).\r\n * L\xEA estado do Script1 (escolherTipo, selecionarResultado, selectMode,\r\n * atualizarPreviewCard, logoRealizadoBase64, logoInstBase64) e do Script3\r\n * (selectedEmoji, salvarConcurso) \u2014 compartilhamento de realm cl\xE1ssico.\r\n * Adapta\xE7\xF5es:\r\n *   1. `window.location.search` \u2192 seam: window.__CT_PAGE_SEARCH__ (a query da\r\n *      navega\xE7\xE3o no plugin, setada pelo shell a cada render; em browser puro,\r\n *      cai no location.search real).\r\n * Nenhuma outra altera\xE7\xE3o.\r\n */\r\n    document.addEventListener('DOMContentLoaded', function () {\r\n      // Verifica se veio de uma edi\xE7\xE3o via URL ?editar=ID\r\n      const params = new URLSearchParams(typeof window.__CT_PAGE_SEARCH__ === 'string' ? window.__CT_PAGE_SEARCH__ : window.location.search);\r\n      const editandoId = params.get('editar');\r\n      const finalizeFlag = params.get('finalizar');\r\n      if (!editandoId) return;\r\n\r\n      const c = CT.getConcurso(editandoId);\r\n      if (!c) return;\r\n\r\n      // Se flag 'finalizar' estiver ativa, for\xE7amos o modo 'realizado' preenchendo com dados do ativo\r\n      if (finalizeFlag === '1' && !c.realizado) {\r\n        escolherTipo('realizado');\r\n        document.getElementById('r_nome').value = c.nome || '';\r\n        document.getElementById('r_cargo').value = c.cargo || '';\r\n        document.getElementById('r_banca').value = c.banca || '';\r\n        document.getElementById('r_data').value = c.dataProva || '';\r\n        document.getElementById('r_vagas').value = c.vagas || '';\r\n        document.getElementById('r_local_prova').value = c.localProva || '';\r\n        selecionarResultado('aguardando');\r\n        \r\n        if (c.logoPath || c.logoBase64) {\r\n          logoRealizadoBase64 = c.logoBase64;\r\n          document.getElementById('previewRImgEl').src = c.logoPath ? (c.logoPath + '?t=' + Date.now()) : c.logoBase64;\r\n          document.getElementById('previewRName').textContent = 'logo salvo';\r\n          document.getElementById('uploadAreaR').style.display = 'none';\r\n          document.getElementById('previewR').style.display = 'flex';\r\n        }\r\n        sessionStorage.setItem('ct_editando_realizado_id', editandoId);\r\n        atualizarPreviewCard();\r\n        return;\r\n      }\r\n\r\n      if (c.realizado) {\r\n        // Abre direto o wizard de realizado\r\n        escolherTipo('realizado');\r\n\r\n        // Preenche os campos\r\n        document.getElementById('r_nome').value = c.nome || '';\r\n        document.getElementById('r_cargo').value = c.cargo || '';\r\n        document.getElementById('r_banca').value = c.banca || '';\r\n        document.getElementById('r_data').value = c.dataProva || '';\r\n\r\n        const ids = {\r\n          r_colocacao: c.colocacao, r_total_candidatos: c.totalCand,\r\n          r_nota_corte: c.notaCorte, r_vagas: c.vagas,\r\n          r_local_prova: c.localProva,\r\n          r_certas: c.certas, r_erradas: c.erradas,\r\n          r_branco: c.branco, r_pontuacao: c.pontuacao, r_pontuacao_maxima: c.pontuacaoMax,\r\n          r_redacao: c.redacao,\r\n          r_obs: c.obs\r\n        };\r\n        Object.entries(ids).forEach(([id, val]) => {\r\n          const el = document.getElementById(id);\r\n          if (el && val != null) el.value = val;\r\n        });\r\n\r\n        const ct2 = document.getElementById('r_contar');\r\n        if (ct2) ct2.checked = !!c.contarEstatisticas;\r\n\r\n        if (c.resultado) selecionarResultado(c.resultado);\r\n\r\n        if (c.logoPath || c.logoBase64) {\r\n          logoRealizadoBase64 = c.logoBase64;\r\n          document.getElementById('previewRImgEl').src = c.logoPath ? (c.logoPath + '?t=' + Date.now()) : c.logoBase64;\r\n          document.getElementById('previewRName').textContent = 'logo salvo';\r\n          document.getElementById('uploadAreaR').style.display = 'none';\r\n          document.getElementById('previewR').style.display = 'flex';\r\n        }\r\n\r\n        // Guarda o id para sobrescrever ao salvar\r\n        sessionStorage.setItem('ct_editando_realizado_id', editandoId);\r\n        atualizarPreviewCard();\r\n      } else {\r\n        // Abre o wizard normal de concurso ativo\r\n        escolherTipo('ativo');\r\n\r\n        // Preenche campos\r\n        const inNome = document.getElementById('a_nome');\r\n        const inCargo = document.getElementById('a_cargo');\r\n        const inBanca = document.getElementById('inputBanca');\r\n        if (inNome) inNome.value = c.nome || '';\r\n        if (inCargo) inCargo.value = c.cargo || '';\r\n        if (inBanca) inBanca.value = c.banca || '';\r\n        const inVagas = document.getElementById('a_vagas');\r\n        const inLocal = document.getElementById('a_local_prova');\r\n        if (inVagas) inVagas.value = c.vagas || '';\r\n        if (inLocal) inLocal.value = c.localProva || '';\r\n\r\n        const dataOpts = document.querySelectorAll('.date-option');\r\n        if (c.preEdital) {\r\n          if (dataOpts.length > 0) selectMode(dataOpts[0], 'pre');\r\n        } else {\r\n          if (dataOpts.length > 1) selectMode(dataOpts[1], 'data');\r\n          if (c.dataProva) {\r\n            const inDate = document.getElementById('a_data');\r\n            if (inDate) inDate.value = c.dataProva;\r\n          }\r\n        }\r\n        if (c.logoPath || c.logoBase64) {\r\n          logoInstBase64 = c.logoBase64;\r\n          document.getElementById('previewInstImgEl').src = c.logoPath ? (c.logoPath + '?t=' + Date.now()) : c.logoBase64;\r\n          document.getElementById('previewInstName').textContent = 'logo salvo';\r\n          document.getElementById('uploadAreaInst').style.display = 'none';\r\n          document.getElementById('previewInst').style.display = 'flex';\r\n        }\r\n        if (c.logoEmoji) selectedEmoji = c.logoEmoji;\r\n\r\n        const st2Next = document.querySelector('#step-2 .btn-next');\r\n        if (st2Next) {\r\n          st2Next.innerHTML = '\u{1F4BE} Salvar edi\xE7\xF5es';\r\n          st2Next.style.background = 'linear-gradient(135deg, var(--yellow), var(--orange))';\r\n          st2Next.onclick = salvarConcurso;\r\n        }\r\n        const sideItems = document.querySelectorAll('#stepsAtivo .step-item');\r\n        if (sideItems.length > 3) {\r\n          sideItems[2].style.display = 'none';\r\n          sideItems[3].style.display = 'none';\r\n        }\r\n        const cnt1 = document.querySelector('#step-1 .step-counter');\r\n        if (cnt1) cnt1.textContent = '1 / 2';\r\n        const cnt2 = document.querySelector('#step-2 .step-counter');\r\n        if (cnt2) cnt2.textContent = '2 / 2';\r\n\r\n        sessionStorage.setItem('ct_editando', editandoId);\r\n        atualizarPreviewCard();\r\n      }\r\n    });\r\n";
