    const noHash = hIdx === -1 ? raw : raw.slice(0, hIdx);
    const qIdx = noHash.indexOf("?");
    this.pendingPageSearch = qIdx === -1 ? "" : noHash.slice(qIdx);
    const name = qIdx === -1 ? noHash : noHash.slice(0, qIdx);
